#include <iostream>
struct Counter {
    int n;
    explicit Counter(int x) : n(x) {}
    Counter& operator++() { ++n; return *this; }
    Counter operator++(int) { Counter old=*this; ++(*this); return old; }
};
int main() {
    Counter x(5);
    Counter a = x++;
    Counter b = ++x;
    std::cout << a.n << ' ' << b.n << ' ' << x.n;
}

